    "question": "癌症病人進行放射線治療時，消化道的那類細胞易受損，其原因為何？",
    "options": {
      "A": "杯狀細胞（goblet cells），因為杯狀細胞產生的黏液會變性",
      "B": "腸嗜鉻細胞（enterochromaffin cells），因為腸嗜鉻細胞的細胞核染色體容易受放射線干擾",
      "C": "平滑肌細胞（smooth muscle cells），因為平滑肌的肌纖維容易斷裂",
      "D": "上皮細胞（epithelial cells），因為上皮細胞的增生替換週期短"
    },
    "answer": "D",
    "explanation": null,
    "verifiedTags": [],
    "source": "考選部 110 年第一次醫事放射師，試題代號 1309，PDF 第 9 頁",
